-- PT107-S1-Q25. Batch 03.
BEGIN;
DO $guard$ BEGIN IF NOT EXISTS (SELECT 1 FROM lr_questions q WHERE q.qid=$batch03$PT107-S1-Q25$batch03$ AND q.stimulus=$batch03$The indigenous people of Tasmania are clearly related to the indigenous people of Australia but were separated from them when the land bridge between Australia and Tasmania disappeared approximately 10,000 years ago. Two thousand years after the disappearance of the land bridge, however, there were major differences between the culture and technology of the indigenous Tasmanians and those of the indigenous Australians. The indigenous Tasmanians, unlike their Australian relatives, had no domesticated dogs, fishing nets, polished stone tools, or hunting implements like the boomerang and the spear-thrower.$batch03$ AND q.prompt=$batch03$Each of the following, if true, would contribute to an explanation of differences described above EXCEPT:$batch03$ AND q.correct_choice=$batch03$B$batch03$) THEN RAISE EXCEPTION 'Question changed: PT107-S1-Q25'; END IF; END $guard$;
DO $guard$ BEGIN IF (SELECT COUNT(*) FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id WHERE q.qid=$batch03$PT107-S1-Q25$batch03$ AND e.style IN ('single','standard')) <> 0 THEN RAISE EXCEPTION 'Explanation row changed: PT107-S1-Q25'; END IF; END $guard$;
INSERT INTO lr_explanations (question_id, style) SELECT q.id, 'single' FROM lr_questions q WHERE q.qid=$batch03$PT107-S1-Q25$batch03$ AND NOT EXISTS (SELECT 1 FROM lr_explanations e WHERE e.question_id=q.id AND e.style IN ('single','standard')) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_steps (explanation_id, position, label, body) SELECT e.id, v.position, v.label, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES (0, $batch03$Given that$batch03$, $batch03$Tasmanians and Australians are related and were separated about 10,000 years ago.$batch03$), (1, $batch03$How can it be that$batch03$, $batch03$Two thousand years later, Tasmanians lacked dogs, nets, polished tools and implements like the boomerang that Australians had?$batch03$), (2, $batch03$Evaluate$batch03$, $batch03$There are only a few routes. The Tasmanians lost things they once had. The Australians gained things after the split, by invention or import. Or the Australians had them before the split, but only in groups the Tasmanians never met. Any of these explains the gap.$batch03$), (3, $batch03$Goal$batch03$, $batch03$Four choices fit one of those routes. The answer will make the gap harder to explain.$batch03$)) v(position,label,body) WHERE q.qid=$batch03$PT107-S1-Q25$batch03$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_steps s WHERE s.explanation_id=e.id) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_choice_notes (explanation_id, letter, body) SELECT e.id, v.letter, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES ($batch03$A$batch03$, $batch03$Tasmanians once had these practices and dropped them. That is the "lost it" route.$batch03$), ($batch03$B$batch03$, $batch03$If Tasmanians developed boomerangs and spear-throwers *before* the split, they should still have had them. This adds to the mystery of why they lacked them later instead of explaining it.$batch03$), ($batch03$C$batch03$, $batch03$Polynesians brought these innovations to Australia after the bridge disappeared. Tasmania was cut off by then, so Tasmanians never got them.$batch03$), ($batch03$D$batch03$, $batch03$Australians invented the boomerang and spear-thrower after the split. Tasmanians could not have received them.$batch03$), ($batch03$E$batch03$, $batch03$The innovations existed before the split, but only among northern groups the Tasmanians never contacted. Separation then kept them out.$batch03$)) v(letter,body) WHERE q.qid=$batch03$PT107-S1-Q25$batch03$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_choice_notes n WHERE n.explanation_id=e.id AND n.letter=v.letter) ON CONFLICT DO NOTHING;
